import { signOut, withAuth } from "@workos-inc/authkit-nextjs";
import { getOrCreateUser, listUsers } from "@/lib/users";

export default async function DashboardPage() {
  // Redirects to sign-in if there's no session.
  const { user: workosUser } = await withAuth({ ensureSignedIn: true });
  const me = getOrCreateUser(workosUser);
  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-start justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <form
          action={async () => {
            "use server";
            await signOut();
          }}
        >
          <button type="submit" className="text-sm underline opacity-70">
            Sign out
          </button>
        </form>
      </div>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me.name} ({me.email})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}
